steps.command:
cat > test_list.c <<'EOF'
#include <stdio.h>
#include "list.h"

/* Stop at the first failed check and say which one. */
#define CHECK(cond) do { if (!(cond)) { \
    fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); return 1; } } while (0)

int main(void)
{
    Node *head = NULL;
    CHECK(list_add(&head, 1, "Leon") == 0);
    CHECK(list_add(&head, 3, NULL) == -1);      /* a contact must have a name */
    CHECK(list_add(&head, 4, "Emma") == 0);
    Node *hit = list_find_by_name(head, "Emma");
    CHECK(hit != NULL && hit->id == 4);
    CHECK(list_find_by_name(head, "Nobody") == NULL);
    list_free(head);
    puts("test_list: all checks passed");
    return 0;
}
EOF
gcc -std=c11 -Wall -Wextra -g test_list.c list.c -o test_list && ./test_list

